"""Original C227824 walker/signal/camera packet writer, without CARLA import.

The caller runs one synchronized CARLA tick, waits for each camera image, and
supplies that snapshot here. This file writes source packets only; it never
seals capture, decodes video, or claims physical acceptance.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path

from native_signal import sample as sample_signal
from saved_entry import CAMERAS, PACKETS


def _finite(value):
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("nonfinite original body coordinate")
    return number


def _body(actor, scene, frame, time_s):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(vertices) != 8:
        raise ValueError("original walker needs eight world-space body vertices")
    xyz = [(_finite(v.x), _finite(v.y), _finite(v.z)) for v in vertices]
    xs, ys = [v[0] for v in xyz], [v[1] for v in xyz]
    if max(xs) - min(xs) < .1 or max(ys) - min(ys) < .1:
        raise ValueError("degenerate original walker footprint")
    # A conservative XY envelope includes every original walker body vertex.
    polygon = [[min(xs), min(ys)], [max(xs), min(ys)],
               [max(xs), max(ys)], [min(xs), max(ys)]]
    return {"case_id": scene["case_id"], "frame": frame, "time_s": time_s,
            "actor_id": int(actor.id), "body_polygon_xy_m": polygon,
            "body_z_min_m": min(v[2] for v in xyz),
            "body_z_max_m": max(v[2] for v in xyz),
            "source_kind": "original_native_world_vertices_envelope"}


def sample_tick(scene, walker, head, others, snapshot, camera_frames):
    """Reject any stale camera image before producing five joined source rows."""
    frame = snapshot.frame
    time_s = snapshot.timestamp.elapsed_seconds
    if type(frame) is not int or frame < 0 or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
        raise ValueError("invalid original world snapshot")
    if not isinstance(camera_frames, dict) or set(camera_frames) != set(CAMERAS):
        raise ValueError("four original camera frames required")
    joins = {}
    for name in CAMERAS:
        image = camera_frames[name]
        if getattr(image, "frame", None) != frame:
            raise ValueError("stale or missing original camera frame: " + name)
        joins[name] = {"frame": frame, "width": int(image.width),
                       "height": int(image.height)}
        if joins[name]["width"] <= 0 or joins[name]["height"] <= 0:
            raise ValueError("invalid original camera dimensions")
    body = _body(walker, scene, frame, float(time_s))
    signal, device = sample_signal(head, others, scene, frame=frame, time_s=time_s)
    common = {"case_id": scene["case_id"], "frame": frame, "time_s": float(time_s)}
    return {"walker-body-history.jsonl": body,
            "signal-history.jsonl": signal,
            "device-history.jsonl": device,
            "video_frames.jsonl": {"video_frame": None, "carla_frame": frame,
                                   "time_s": float(time_s)},
            "camera-frame-joins.jsonl": {**common, "cameras": joins}}


class PacketWriter:
    """Append exact synchronized packet groups to a private attempt directory."""

    def __init__(self, attempt):
        self.root = Path(attempt).resolve()
        source = Path(__file__).resolve()
        bundled = next((parent for parent in source.parents
                        if parent.name == ".runtime-work"), None)
        private = (bundled if bundled is not None else source.parents[2] / ".runtime-work").resolve()
        if not self.root.is_dir() or not self.root.is_relative_to(private):
            raise ValueError("Native attempt must exist under .runtime-work")
        self.streams = {}
        for name in PACKETS:
            if (self.root / name).exists():
                raise ValueError("original packet file already exists: " + name)
        try:
            for name in PACKETS:
                self.streams[name] = (self.root / name).open("x", buffering=1)
        except BaseException:
            self.close()
            raise
        self.count = 0
        self.last_frame = -1
        self.last_time = -math.inf

    def append(self, packets):
        if set(packets) != set(PACKETS):
            raise ValueError("incomplete original packet group")
        body = packets["walker-body-history.jsonl"]
        frame, time_s = body["frame"], body["time_s"]
        if frame <= self.last_frame or time_s <= self.last_time:
            raise ValueError("original packet frames must be strictly increasing")
        for name in PACKETS:
            row = packets[name]
            if name == "video_frames.jsonl":
                if row.get("carla_frame") != frame or row.get("time_s") != time_s:
                    raise ValueError("original frame-map join differs")
            elif row.get("frame") != frame or row.get("time_s") != time_s or row.get("case_id") != body.get("case_id"):
                raise ValueError("original packet time/case join differs")
        packets["video_frames.jsonl"]["video_frame"] = self.count
        encoded = {name: json.dumps(packets[name], allow_nan=False) + "\n" for name in PACKETS}
        for name in PACKETS:
            self.streams[name].write(encoded[name])
        self.count += 1
        self.last_frame, self.last_time = frame, time_s

    def close(self):
        for stream in self.streams.values():
            stream.close()
        self.streams = {}


def source_hashes(attempt):
    """Hash completed source bytes after encoder exit; no seal claim is made."""
    root = Path(attempt).resolve()
    names = ("scene.json", *PACKETS, *(camera + ".mkv" for camera in CAMERAS))
    if (root / "trace.jsonl").exists():
        names += ("trace.jsonl",)
    hashes = {}
    for name in names:
        path = root / name
        if not path.is_file() or not path.stat().st_size:
            raise ValueError("missing completed original source: " + name)
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        hashes[name] = {"sha256": digest.hexdigest()}
    return hashes

"""Bind and sample original signal actors for C227824 pedestrian entry.

The scene must supply a reviewed, source-hashed inventory of every device that
governs this route. Actor metadata and readback are required; CARLA's bare Red
state does not prove a steady red signal alone or pedestrian authority.
"""
from __future__ import annotations

import math


DEVICES = {"walk", "flashing_hand_countdown", "flashing_hand_no_countdown",
           "steady_hand"}


def _state(actor):
    return str(actor.get_state()).split(".")[-1].lower()


def _review(scene):
    review = scene.get("device_inventory_review")
    if not isinstance(review, dict) or review.get("complete") is not True:
        raise ValueError("complete governing-device review missing")
    digest = review.get("source_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise ValueError("governing-device review source hash missing")
    route = scene.get("route_id")
    if not isinstance(route, str) or not route:
        raise ValueError("pedestrian route identity missing")
    ids = scene.get("governing_pedestrian_device_ids")
    if not isinstance(ids, list) or len(ids) != len(set(ids)) or any(type(i) is not int or i < 0 for i in ids):
        raise ValueError("governing-device inventory invalid")
    head_id = scene.get("facing_head_id")
    if type(head_id) is not int or head_id < 0 or head_id in ids:
        raise ValueError("facing traffic signal identity invalid")
    return route, ids, head_id


def bind(world, scene):
    """Resolve exact original actors and require route/authority metadata."""
    route, ids, head_id = _review(scene)
    all_actors = world.get_actors()
    if all_actors is None:
        raise ValueError("original world actor inventory unavailable")
    inventoried = sorted(actor.id for actor in all_actors
                         if actor.attributes.get("official_pedestrian_signal") == "true"
                         and actor.attributes.get("governs_pedestrian_route_id") == route)
    if inventoried != sorted(ids):
        raise ValueError("original governing pedestrian device inventory differs")
    head = world.get_actor(head_id)
    if head is None or head.attributes.get("official_traffic_signal") != "true" or head.attributes.get("governs_pedestrian_route_id") != route:
        raise ValueError("official route-facing traffic head absent")
    if head.attributes.get("signal_shape") != "circle" or head.attributes.get("sole_illuminated") != "true":
        raise ValueError("source asset does not establish red alone")
    others = []
    for actor_id in ids:
        actor = world.get_actor(actor_id)
        if actor is None or actor.attributes.get("official_pedestrian_signal") != "true" or actor.attributes.get("governs_pedestrian_route_id") != route:
            raise ValueError("reviewed official pedestrian device absent")
        others.append(actor)
    return head, others


def configure(head, others, scene, carla):
    """Request red alone and a specified other indication, then read back."""
    _, ids, _ = _review(scene)
    requested = scene.get("requested_pedestrian_indication")
    if requested not in DEVICES | {"none"}:
        raise ValueError("unsupported pedestrian indication")
    if (requested == "none") != (len(ids) == 0):
        raise ValueError("requested indication disagrees with reviewed device inventory")
    head.set_state(carla.TrafficLightState.Red)
    head.freeze(True)
    if _state(head) != "red":
        raise ValueError("traffic head did not read back red")
    if requested != "none":
        if len(others) != 1 or not callable(getattr(others[0], "set_pedestrian_indication", None)):
            raise ValueError("source-backed pedestrian indication driver unavailable")
        others[0].set_pedestrian_indication(requested)
        if _state(others[0]) != requested:
            raise ValueError("pedestrian indication did not read back")
    return {"facing_head_id": head.id, "other_device_ids": [actor.id for actor in others],
            "requested_pedestrian_indication": requested,
            "original_readback_confirmed": True, "actual_pixels_verified": False}


def sample(head, others, scene, *, frame, time_s):
    """Return source packets for the same original world snapshot/frame."""
    route, ids, head_id = _review(scene)
    if type(frame) is not int or frame < 0 or not isinstance(time_s, (int, float)) or not math.isfinite(time_s):
        raise ValueError("invalid original signal frame")
    if head.id != head_id or [actor.id for actor in others] != ids:
        raise ValueError("original signal actors changed")
    if (head.attributes.get("official_traffic_signal") != "true" or
            head.attributes.get("governs_pedestrian_route_id") != route or
            head.attributes.get("signal_shape") != "circle" or
            head.attributes.get("sole_illuminated") != "true"):
        raise ValueError("original route-facing signal authority changed")
    if _state(head) != "red":
        raise ValueError("facing traffic head not red in original frame")
    common = {"case_id": scene["case_id"], "frame": frame, "time_s": float(time_s)}
    signal = {**common, "facing_traffic_signal": {
        "official": True, "indication": "steady_red_alone",
        "head_id": head.id, "route_id": route,
        "asset_source_sha256": scene["device_inventory_review"]["source_sha256"]}}
    devices = []
    requested = scene.get("requested_pedestrian_indication")
    for actor in others:
        if (actor.attributes.get("official_pedestrian_signal") != "true" or
                actor.attributes.get("governs_pedestrian_route_id") != route):
            raise ValueError("original pedestrian device authority changed")
        indication = _state(actor)
        if indication not in DEVICES:
            raise ValueError("unsupported original pedestrian device state")
        if indication != requested:
            raise ValueError("original pedestrian indication differs from requested case")
        device = {"official": True, "indication": indication, "head_id": actor.id,
                  "route_id": route}
        if indication == "flashing_hand_countdown":
            get_countdown = getattr(actor, "get_countdown", None)
            if not callable(get_countdown):
                raise ValueError("original pedestrian countdown readback unavailable")
            count = get_countdown()
            if not isinstance(count, (int, float)) or not math.isfinite(count) or count < 0:
                raise ValueError("invalid original pedestrian countdown")
            device["countdown_s"] = float(count)
        devices.append(device)
    return signal, {**common, "other_devices": devices}

"""Spawn four reviewed C227824 source cameras on a CARLA world."""
from __future__ import annotations

import math

from native_recorder import SIZES
from saved_entry import CAMERAS


def _xyz(point):
    if not isinstance(point, (list, tuple)) or len(point) != 3:
        raise ValueError("reviewed camera location/target must be xyz")
    values = tuple(float(value) for value in point)
    if not all(math.isfinite(value) for value in values):
        raise ValueError("nonfinite reviewed camera location/target")
    return values


def placements(scene):
    review = scene.get("camera_placement_review")
    if not isinstance(review, dict) or review.get("complete") is not True:
        raise ValueError("complete original camera placement review missing")
    digest = review.get("source_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(c not in "0123456789abcdef" for c in digest):
        raise ValueError("original camera placement source hash missing")
    cameras = scene.get("camera_placements")
    if not isinstance(cameras, dict) or set(cameras) != set(CAMERAS):
        raise ValueError("four reviewed camera placements required")
    result = {}
    for name in CAMERAS:
        item = cameras[name]
        if not isinstance(item, dict):
            raise ValueError("reviewed camera placement missing: " + name)
        x, y, z = _xyz(item.get("location_xyz_m"))
        tx, ty, tz = _xyz(item.get("target_xyz_m"))
        distance = math.hypot(tx - x, ty - y)
        if distance <= .1 or z <= .2:
            raise ValueError("degenerate original camera aim: " + name)
        yaw = math.degrees(math.atan2(ty - y, tx - x))
        pitch = math.degrees(math.atan2(tz - z, distance))
        result[name] = ((x, y, z), (pitch, yaw))
    return result


def spawn(world, carla, scene):
    """Construct four RGB sensors; destroy partial spawns on failure."""
    sites = placements(scene)
    sensors = {}
    try:
        for name in CAMERAS:
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            if blueprint is None:
                raise ValueError("Native RGB camera blueprint missing")
            width, height = SIZES[name]
            for key, value in (("image_size_x", width), ("image_size_y", height), ("fov", 75)):
                blueprint.set_attribute(key, str(value))
            (x, y, z), (pitch, yaw) = sites[name]
            transform = carla.Transform(carla.Location(x=x, y=y, z=z),
                                        carla.Rotation(pitch=pitch, yaw=yaw))
            sensor = world.spawn_actor(blueprint, transform)
            if sensor is None:
                raise ValueError("Native RGB camera spawn failed: " + name)
            sensors[name] = sensor
        return sensors
    except BaseException:
        for sensor in reversed(list(sensors.values())):
            sensor.destroy()
        raise

"""Four original RGB camera streams for a private C227824 Native attempt.

The caller supplies four already placed CARLA sensors. Source-reviewed camera
placement and independent decode/sealing remain separate requirements.
"""
from __future__ import annotations

import queue
import subprocess
from pathlib import Path

from saved_entry import CAMERAS


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class FourStreamRecorder:
    """Own four sensor subscriptions and encoders; fail closed on lost frames."""

    def __init__(self, sensors, output, encoder_factory=None):
        if not isinstance(sensors, dict) or set(sensors) != set(CAMERAS):
            raise ValueError("four named original RGB sensors required")
        self.output = Path(output).resolve()
        if not self.output.is_dir() or any((self.output / (name + ".mkv")).exists() for name in CAMERAS):
            raise ValueError("fresh Native video output directory required")
        self.sensors = sensors
        self.queues = {name: queue.Queue(maxsize=4) for name in CAMERAS}
        self.encoders = {}
        self.errors = []
        self.closed = False
        self.count = 0
        encoder_factory = encoder_factory or subprocess.Popen
        try:
            for name in CAMERAS:
                inbox = self.queues[name]

                def receive(image, target=inbox, label=name):
                    try:
                        target.put_nowait(image)
                    except queue.Full:
                        self.errors.append("original camera queue overflow: " + label)

                sensors[name].listen(receive)
                width, height = SIZES[name]
                command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                           "-n", "-f", "rawvideo", "-pixel_format", "bgra",
                           "-video_size", f"{width}x{height}", "-framerate", "20",
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-pix_fmt", "bgra",
                           str(self.output / (name + ".mkv"))]
                self.encoders[name] = encoder_factory(
                    command, stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def capture(self, frame):
        if self.closed or self.errors:
            raise RuntimeError("closed or failed original camera recorder: " + "; ".join(self.errors))
        images = {}
        for name in CAMERAS:
            try:
                image = self.queues[name].get(timeout=15)
            except queue.Empty as exc:
                raise RuntimeError("missing original camera frame: " + name) from exc
            width, height = SIZES[name]
            if (image.frame != frame or image.width != width or image.height != height
                    or len(image.raw_data) != width * height * 4):
                raise ValueError("stale or invalid original camera frame: " + name)
            images[name] = image
        return images

    def append(self, images):
        if self.closed or self.errors or set(images) != set(CAMERAS):
            raise ValueError("incomplete original camera group")
        for name in CAMERAS:
            image = images[name]
            width, height = SIZES[name]
            if image.width != width or image.height != height or len(image.raw_data) != width * height * 4:
                raise ValueError("invalid original camera bytes: " + name)
        for name in CAMERAS:
            data = images[name].raw_data
            if self.encoders[name].stdin.write(data) != len(data):
                raise RuntimeError("incomplete original video write: " + name)
        self.count += 1

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in self.sensors.values():
            try:
                sensor.stop()
            except BaseException as exc:
                errors.append("camera stop: " + repr(exc))
        for name, encoder in self.encoders.items():
            try:
                encoder.stdin.close()
                if encoder.wait(timeout=180) != 0:
                    errors.append("original encoder failed: " + name)
            except BaseException as exc:
                errors.append("original encoder close: " + repr(exc))
        if errors:
            raise RuntimeError("; ".join(errors))

"""Lazy CARLA walker request for the C227824 entry and wait cases.

The caller owns actor creation, the source-hashed scene, signal timing and world
ticks. This controller only issues a movement request; it never claims motion.
"""
from __future__ import annotations

import math


def _xy(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("walker target must be an xy pair")
    result = tuple(float(v) for v in value)
    if not all(math.isfinite(v) for v in result):
        raise ValueError("walker target is nonfinite")
    return result


def request(actor, carla, *, entry_request, target_xy_m, speed_mps):
    """Request walk toward a map-reviewed target or hold position outside."""
    if entry_request not in {"entry", "wait"}:
        raise ValueError("unsupported walker request")
    target = _xy(target_xy_m)
    if not isinstance(speed_mps, (int, float)) or not math.isfinite(speed_mps) or speed_mps <= 0 or speed_mps > 3:
        raise ValueError("walker speed must be finite and within engineering bounds")
    position = actor.get_transform().location
    x, y = float(position.x), float(position.y)
    if not all(math.isfinite(v) for v in (x, y)):
        raise ValueError("nonfinite original walker position")
    if entry_request == "wait":
        direction = carla.Vector3D(0, 0, 0)
        requested_speed = 0.0
    else:
        dx, dy = target[0] - x, target[1] - y
        distance = math.hypot(dx, dy)
        if distance <= 0.05:
            direction = carla.Vector3D(0, 0, 0)
            requested_speed = 0.0
        else:
            direction = carla.Vector3D(dx / distance, dy / distance, 0)
            requested_speed = float(speed_mps)
    control = carla.WalkerControl(direction=direction, speed=requested_speed, jump=False)
    actor.apply_control(control)
    return {"requested_speed_mps": requested_speed,
            "target_xy_m": list(target), "entry_request": entry_request,
            "applied": True, "realized_motion_claimed": False}

"""Saved-source measurement of pedestrian entry while facing a steady red signal.

This module measures source events. It does not decide legal permission or infer
that an authored signal/device was visible in the recorded pixels.
"""
from __future__ import annotations

import math


def _point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("expected a two-coordinate point")
    pair = tuple(float(v) for v in value)
    if not all(math.isfinite(v) for v in pair):
        raise ValueError("nonfinite point")
    return pair


def _polygon(value):
    if not isinstance(value, list) or len(value) < 3:
        raise ValueError("polygon needs at least three vertices")
    return [_point(v) for v in value]


def _orient(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _on_segment(a, b, p):
    return abs(_orient(a, b, p)) <= 1e-9 and min(a[0], b[0]) - 1e-9 <= p[0] <= max(a[0], b[0]) + 1e-9 and min(a[1], b[1]) - 1e-9 <= p[1] <= max(a[1], b[1]) + 1e-9


def _segments_meet(a, b, c, d):
    x, y, z, w = (_orient(a, b, c), _orient(a, b, d),
                  _orient(c, d, a), _orient(c, d, b))
    if (x > 0 > y or y > 0 > x) and (z > 0 > w or w > 0 > z):
        return True
    return any((_on_segment(a, b, c), _on_segment(a, b, d),
                _on_segment(c, d, a), _on_segment(c, d, b)))


def _contains(polygon, point):
    inside = False
    for index, a in enumerate(polygon):
        b = polygon[(index + 1) % len(polygon)]
        if _on_segment(a, b, point):
            return True
        if (a[1] > point[1]) != (b[1] > point[1]):
            x = a[0] + (point[1] - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
            if point[0] < x:
                inside = not inside
    return inside


def polygons_overlap(first, second):
    """Boundary contact counts as entry; the highway includes its boundary."""
    a, b = _polygon(first), _polygon(second)
    if any(_contains(b, p) for p in a) or any(_contains(a, p) for p in b):
        return True
    return any(_segments_meet(a[i], a[(i + 1) % len(a)], b[j], b[(j + 1) % len(b)])
               for i in range(len(a)) for j in range(len(b)))


def measure_entry(rows, highway_polygon):
    """Return first full-body entry event from original synchronized samples.

    Each row must carry the source frame, time, body outline, facing traffic
    signal, and inventory of other governing devices. Missing indication data
    fails closed. The first row must be wholly outside the highway.
    """
    highway = _polygon(highway_polygon)
    if not rows:
        raise ValueError("original frame samples missing")
    previous_frame = -1
    previous_time = -math.inf
    first_entry = None
    first_clear_after_entry = None
    first_countdown_zero = None
    outside_initially = False
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise ValueError("invalid original frame sample")
        frame = row.get("frame")
        time_s = row.get("time_s")
        if not isinstance(frame, int) or isinstance(frame, bool) or frame <= previous_frame:
            raise ValueError("frames must be strictly increasing")
        if not isinstance(time_s, (float, int)) or not math.isfinite(time_s) or time_s <= previous_time:
            raise ValueError("times must be strictly increasing")
        previous_frame, previous_time = frame, time_s
        overlap = polygons_overlap(row.get("body_polygon_xy_m"), highway)
        if index == 0:
            outside_initially = not overlap
            if not outside_initially:
                raise ValueError("first original body sample is already inside highway")
        traffic = row.get("facing_traffic_signal")
        if not isinstance(traffic, dict) or traffic.get("indication") not in {"steady_red_alone", "other"} or traffic.get("official") is not True:
            raise ValueError("facing official traffic signal source missing")
        devices = row.get("other_devices")
        if not isinstance(devices, list):
            raise ValueError("other governing device inventory missing")
        for device in devices:
            if not isinstance(device, dict) or device.get("indication") not in {"walk", "flashing_hand_countdown", "flashing_hand_no_countdown", "steady_hand", "other"} or not isinstance(device.get("official"), bool):
                raise ValueError("other device indication source missing")
            if device["indication"] == "flashing_hand_countdown":
                count = device.get("countdown_s")
                if not isinstance(count, (int, float)) or not math.isfinite(count) or count < 0:
                    raise ValueError("countdown source missing")
                if count == 0 and first_countdown_zero is None:
                    first_countdown_zero = {"frame": frame, "time_s": time_s}
        if overlap and first_entry is None:
            first_entry = {"frame": frame, "time_s": time_s,
                           "facing_traffic_signal": traffic.copy(),
                           "other_devices": [d.copy() for d in devices]}
        if first_entry is not None and not overlap and first_clear_after_entry is None:
            first_clear_after_entry = {"frame": frame, "time_s": time_s}
    return {"outside_highway_at_start": outside_initially,
            "first_entry": first_entry,
            "first_clear_after_entry": first_clear_after_entry,
            "first_countdown_zero": first_countdown_zero,
            "cleared_before_countdown_zero": (
                first_clear_after_entry["frame"] < first_countdown_zero["frame"]
                if first_clear_after_entry is not None and first_countdown_zero is not None
                else None),
            "entry_observed": first_entry is not None,
            "sample_count": len(rows),
            "measurement_only": True,
            "legal_permission_determined": False}

"""Independent diagnostic comparison of C227824 saved measurements.

The paired audit verifies source joins and controlled conditions. It does not
interpret NRS 484B.283 or certify a Native recording.
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from saved_entry import build_report


def audit_pair(left, right, *, comparison_id, deliberate_difference):
    if deliberate_difference not in {"entry_request", "other_device_indication"}:
        raise ValueError("undeclared comparison variable")
    if not isinstance(comparison_id, str) or not comparison_id:
        raise ValueError("comparison identity missing")
    if not isinstance(left, dict) or not isinstance(right, dict):
        raise ValueError("paired saved reports missing")
    for report in (left, right):
        for key in ("case_id", "map_sha256", "highway_boundary_sha256",
                    "facing_signal_id", "actor_blueprint", "route_id",
                    "camera_plan_sha256", "entry_request", "measurement"):
            if key not in report or report[key] is None or report[key] == "":
                raise ValueError("paired saved report missing " + key)
        measured = report["measurement"]
        if not isinstance(measured, dict) or measured.get("measurement_only") is not True or measured.get("legal_permission_determined") is not False:
            raise ValueError("unbound or overclaimed entry measurement")
        event = measured.get("first_entry")
        if measured.get("entry_observed") is not (event is not None):
            raise ValueError("entry event disagrees with measurement status")
        if event is not None:
            signal = event.get("facing_traffic_signal")
            if not isinstance(signal, dict) or signal.get("official") is not True or signal.get("indication") != "steady_red_alone":
                raise ValueError("entry frame lacks official facing steady red alone")
            if not isinstance(event.get("other_devices"), list):
                raise ValueError("entry frame lacks other-device inventory")
    if left["case_id"] == right["case_id"]:
        raise ValueError("comparison requires different exact cases")
    fixed = ("map_sha256", "highway_boundary_sha256", "facing_signal_id",
             "actor_blueprint", "route_id", "camera_plan_sha256")
    for key in fixed:
        if left[key] != right[key]:
            raise ValueError("fixed comparison condition differs: " + key)
    if deliberate_difference == "entry_request":
        if {left["entry_request"], right["entry_request"]} != {"entry", "wait"}:
            raise ValueError("entry/wait movement request was not isolated")
        for report in (left, right):
            if report.get("planned_device_indication") != "none":
                raise ValueError("entry/wait comparison changed another device")
    else:
        if left["entry_request"] != "entry" or right["entry_request"] != "entry":
            raise ValueError("device comparison changed movement request")
        if left.get("planned_device_indication") == right.get("planned_device_indication"):
            raise ValueError("separate device indication did not vary")
        if "none" not in {left.get("planned_device_indication"), right.get("planned_device_indication")}:
            raise ValueError("device comparison needs red-alone reference")
        for report in (left, right):
            event = report["measurement"]["first_entry"]
            if event is None:
                raise ValueError("device comparison lacks observed first entry")
            indications = [device.get("indication") for device in event["other_devices"] if device.get("official") is True]
            expected = report["planned_device_indication"]
            if expected == "none" and indications:
                raise ValueError("red-alone reference has another official device")
            if expected != "none" and indications != [expected]:
                raise ValueError("planned device disagrees with original entry frame")
    return {"comparison_id": comparison_id, "case_ids": [left["case_id"], right["case_id"]],
            "fixed_source_conditions_checked": list(fixed),
            "deliberate_difference_checked": deliberate_difference,
            "diagnostic_audit_passed": True,
            "physical_acceptance_claimed": False,
            "legal_verdict_claimed": False}


def audit_attempts(left_attempt, right_attempt, comparison_id, plan_path):
    """Read source-bound saved attempts and enforce the frozen comparison pair."""
    plan = json.loads(Path(plan_path).read_text())
    matches = [item for item in plan["comparisons"]
               if item["comparison_id"] == comparison_id]
    if len(matches) != 1:
        raise ValueError("exact comparison identity missing")
    left = build_report(left_attempt)
    right = build_report(right_attempt)
    pair = matches[0]
    if [left["case_id"], right["case_id"]] != pair["case_ids"]:
        raise ValueError("saved attempts differ from exact comparison pair")
    difference = ("entry_request" if comparison_id == "red_entry_vs_wait"
                  else "other_device_indication")
    result = audit_pair(left, right, comparison_id=comparison_id,
                        deliberate_difference=difference)
    result["source_sha256"] = {left["case_id"]: left["source_sha256"],
                               right["case_id"]: right["source_sha256"]}
    result["diagnostic_fixture"] = (left["diagnostic_fixture"] or
                                     right["diagnostic_fixture"])
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--left-attempt", required=True)
    parser.add_argument("--right-attempt", required=True)
    parser.add_argument("--comparison-id", required=True)
    parser.add_argument("--plan", default=str(Path(__file__).resolve().parent /
                                               "case-plan.json"))
    parser.add_argument("--output", required=True)
    args = parser.parse_args(argv)
    result = audit_attempts(args.left_attempt, args.right_attempt,
                            args.comparison_id, args.plan)
    Path(args.output).write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps({"comparison_id": result["comparison_id"],
                      "diagnostic_fixture": result["diagnostic_fixture"]}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

